class OrbitalCraft {
    constructor(id) {
        this.id = id;
    }

    getInfo() {
        return `Craft ID: ${this.id}`;
    }

    executeMission() {
        throw new Error("executeMission() must be implemented by subclasses.");
    }
}

class Satellite extends OrbitalCraft {
    constructor(id, purpose) {
        super(id);
        this.purpose = purpose;
    }

    executeMission() {
        return `broadcasting ${this.purpose} data.`;
    }
}

class Probe extends OrbitalCraft {
    constructor(id, targetPlanet) {
        super(id);
        this.targetPlanet = targetPlanet;
    }

    executeMission() {
        return `collecting atmospheric data from ${this.targetPlanet}.`;
    }
}

